from unittest import mock

from django.apps import apps
from django.contrib.contenttypes.management import RenameContentType
from django.contrib.contenttypes.models import ContentType
from django.test import TestCase, override_settings


class WriteToDefaultRouter:
    def db_for_write(self, model, **hints):
        return 'default'


@override_settings(DATABASE_ROUTERS=[WriteToDefaultRouter()])
class RenameContentTypeOtherDatabaseTests(TestCase):
    databases = {'default', 'other'}

    def setUp(self):
        ContentType.objects.clear_cache()
        self.addCleanup(ContentType.objects.clear_cache)

    def test_rename_saves_on_schema_editor_database(self):
        # Same primary key in both databases so that a save on the wrong
        # database doesn't crash but silently updates the wrong row.
        for alias in ('default', 'other'):
            ContentType.objects.db_manager(alias).create(
                pk=10001, app_label='contenttypes_tests', model='renamefoo',
            )
        schema_editor = mock.Mock()
        schema_editor.connection.alias = 'other'
        operation = RenameContentType('contenttypes_tests', 'renamefoo', 'renamebar')
        operation.rename_forward(apps, schema_editor)
        self.assertTrue(
            ContentType.objects.using('other').filter(
                app_label='contenttypes_tests', model='renamebar',
            ).exists()
        )
        self.assertFalse(
            ContentType.objects.using('other').filter(
                app_label='contenttypes_tests', model='renamefoo',
            ).exists()
        )
        # The default database must be left untouched.
        self.assertTrue(
            ContentType.objects.using('default').filter(
                app_label='contenttypes_tests', model='renamefoo',
            ).exists()
        )

