class InstanceOnlyDescriptor:
    def __init__(self, field):
        self.field = field

    def __get__(self, instance, owner=None):
        if instance is None:
            raise AttributeError('Only accessible via instance.')
        return instance.__dict__.get(self.field.attname)

    def __set__(self, instance, value):
        instance.__dict__[self.field.attname] = value


class InstanceOnlyField(models.IntegerField):
    def contribute_to_class(self, cls, name, private_only=False):
        super().contribute_to_class(cls, name, private_only=private_only)
        setattr(cls, self.attname, InstanceOnlyDescriptor(self))


class ListDisplayInstanceOnlyFieldTests(SimpleTestCase):
    @isolate_apps('modeladmin')
    def test_list_display_field_only_accessible_via_instance(self):
        class Thing(models.Model):
            number = models.IntegerField(default=0)
            order = InstanceOnlyField(default=0)

            class Meta:
                app_label = 'modeladmin'

        self.assertFalse(hasattr(Thing, 'order'))

        class ThingAdmin(ModelAdmin):
            list_display = ['number', 'order']

        self.assertEqual(ThingAdmin(Thing, AdminSite()).check(), [])

