from django.test import TestCase, skipUnlessDBFeature

from .models import Number


@skipUnlessDBFeature('supports_select_union')
class UnionNoneTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        Number.objects.bulk_create(Number(num=i, other_num=10 - i) for i in range(8))

    def test_none_on_union_returns_empty(self):
        qs1 = Number.objects.filter(num__lt=2)
        qs2 = Number.objects.filter(num__gt=5)
        combined = qs1.union(qs2)
        self.assertEqual(combined.count(), 4)
        self.assertEqual(list(combined.none()), [])
        self.assertEqual(combined.none().count(), 0)
        self.assertFalse(combined.none().exists())

