from sympy import I, Symbol, cos, simplify
from sympy.simplify.fu import TR6


def test_simplify_cos_pow_I():
    x = Symbol('x')
    e = cos(x)**I
    try:
        r = simplify(e)
    except TypeError:
        r = None
    assert r == e


