    except TypeError:
        r = None
    assert r == e

from types import SimpleNamespace

from sympy import Symbol, sympify, simplify


class _Leaf(SimpleNamespace):
    """Minimal stand-in for an antlr parse tree node used by convert_frac."""

    def getSourceInterval(self):
        return (0, 3)


def _leaf(val):
    return _Leaf(val=val,
                 start=SimpleNamespace(type=-1, text='', ),
                 stop=SimpleNamespace(type=-2, text=''))


def _frac(upper, lower):
    return SimpleNamespace(upper=upper, lower=lower)


def test_nested_frac_denominator_brackets():
    from sympy.parsing.latex import _parse_latex_antlr as mod

    a, b, c = Symbol('a'), Symbol('b'), Symbol('c')

    orig = mod.convert_expr
    mod.convert_expr = lambda node: node.val
    try:
        inner_top = mod.convert_frac(_frac(_leaf(a**3 + b), _leaf(c)))
        inner_bot = mod.convert_frac(_frac(_leaf(sympify(1)), _leaf(c**2)))
        expr = mod.convert_frac(_frac(_leaf(inner_top), _leaf(inner_bot)))
    finally:
        mod.convert_expr = orig

    # the printed string must round-trip to the mathematically correct value
    # ((a**3 + b)/c)/(1/c**2) == (a**3 + b)*c
    reparsed = sympify(str(expr), locals={'a': a, 'b': b, 'c': c})
    assert simplify(reparsed - (a**3 + b)*c) == 0
